import json

# Load the grid
with open('/tmp/grid_input_06c1be80.json', 'r') as f:
    grid = json.load(f)

# Apply transformation: wherever pattern is 0-1-0 horizontally, change the 1 to 2
output = []
for r in range(len(grid)):
    row = grid[r][:]  # Copy
    for c in range(len(row) - 1):
        if row[c] == 0 and row[c+1] == 0 and (c+2 < len(row)):
            # Check 0-1-0 pattern
            if row[c-1] == 0 and row[c] == 1:
                pass
    for c in range(1, len(row) - 1):
        if grid[r][c-1] == 0 and grid[r][c] == 1 and grid[r][c+1] == 0:
            row[c] = 2
    output.append(row)

# Let's verify the number of changes
changes = 0
for r in range(len(output)):
    for c in range(len(output[0])):
        if output[r][c] == 2:
            changes += 1

print(f"Total changes made: {changes}")

# Save and print first few rows to verify
print("\nFirst 5 rows of output:")
for r in range(min(5, len(output))):
    print(output[r])
